const hour = Number($now.setZone('America/Sao_Paulo').toFormat('H'));
return items.map(item => {
  const c = item.json;
  const start = Number(c.allowed_start_hour ?? 9);
  const end = Number(c.allowed_end_hour ?? 18);
  const inBusinessHours = hour >= start && hour < end;
  return { json: { ...c, inBusinessHours, blockReason: inBusinessHours ? null : 'fora_horario_comercial' } };
});

const campanha = $('04 - Guardrail Campanha e Horário').first().json;
function cleanPhone(v) { return String(v || '').replace(/\D/g, ''); }
return items.map(item => {
  const phone = cleanPhone(item.json.telefone_e164);
  const validPhone = /^55\d{10,11}$/.test(phone);
  const validOptIn = Boolean(item.json.opt_in_at && item.json.consentimento_texto);
  return { json: { ...item.json, telefone_e164: phone, campanha_id: campanha.id, template_id: campanha.template_id, validPhone, validOptIn, eligible: validPhone && validOptIn } };
});

const contato = $('07 - Validar Opt-in e Normalizar Telefone').first().json;
const campanha = $('04 - Guardrail Campanha e Horário').first().json;
const template = $('09 - Buscar Template Aprovado').first()?.json || {};
const volume = $('10 - Checar Volume Hora Dia').first()?.json || {};
const hourlyLimit = Number(campanha.hourly_limit || 10);
const dailyLimit = Number(campanha.daily_limit || 50);
const enviadosHora = Number(volume.enviados_hora || 0);
const enviadosDia = Number(volume.enviados_dia || 0);
const canSend = template.nome_meta && enviadosHora < hourlyLimit && enviadosDia < dailyLimit;
return [{ json: { contato, campanha, template, volume: { enviadosHora, enviadosDia, hourlyLimit, dailyLimit }, canSend, blockReason: canSend ? null : 'limite_ou_template_invalido' } }];

