insert into respostas (contato_id, telefone_e164, wamid, texto, payload)
select id, '{{ $json.telefone_e164 }}', '{{ $json.wamid }}', '{{ ($json.texto || "").replace(/'/g, "''") }}', '{{ JSON.stringify($json.payload || {}).replace(/'/g, "''") }}'::jsonb
from contatos where telefone_e164 = '{{ $json.telefone_e164 }}';

