const words = ['parar','sair','cancelar','remover'];
return items.map(item => {
  const texto = String(item.json.texto || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
  return { json: { ...item.json, isOptOut: words.includes(texto), optOutWord: words.includes(texto) ? texto : null } };
});

